package api

import (
	"net/http"
	"regexp"
	"strings"
	"testing"
)

// The official "maintenance" JS plugin (plugins-official/maintenance) — the port of the built-in Go
// plugin: the 503 page, exempt paths, the bypass link and cookie (TestMaintenance), the generated bypass
// key (TestEnsureBypassKey / TestBypassKeyStored), the admin page and legacyImport.
func TestOfficialMaintenance(t *testing.T) {
	e := newPluginAPI(t)
	c := e.c
	admin, user := setupSite(t, c)
	if code, b := admin.do("POST", "/api/v1/posts", map[string]any{"type": "page", "title": "About", "slug": "about", "status": "publish", "content": "<p>real site</p>"}); code != 201 {
		t.Fatalf("page: %d %v", code, b)
	}
	offAInstall(t, admin, "maintenance")
	offASiteCode(t, admin, "")
	get := func(url string, cookies ...*http.Cookie) (int, http.Header, string) {
		t.Helper()
		h := map[string]string{}
		if len(cookies) > 0 {
			var parts []string
			for _, ck := range cookies {
				parts = append(parts, ck.Name+"="+ck.Value)
			}
			h["Cookie"] = strings.Join(parts, "; ")
		}
		r := c.send("GET", url, nil, h)
		return r.Code, r.Header(), r.Body.String()
	}

	// off by default
	if code, _, body := get("/about"); code != 200 || !strings.Contains(body, "real site") {
		t.Fatalf("disabled: %d", code)
	}
	offAPkgSettings(t, admin, "maintenance", map[string]any{"enabled": true, "title": "Back <soon>", "message": "Hi\nthere", "bypassKey": "s3cret"})
	code, hdr, body := get("/about")
	if code != 503 || hdr.Get("Retry-After") != "3600" || hdr.Get("Cache-Control") != "no-store" || !strings.HasPrefix(hdr.Get("Content-Type"), "text/html") ||
		!strings.Contains(body, "<h1>Back &lt;soon&gt;</h1>") || !strings.Contains(body, "Hi<br>there") || !strings.Contains(body, `<meta name="robots" content="noindex">`) ||
		!strings.Contains(body, "<title>Back &lt;soon&gt; – S</title>") || !strings.Contains(body, "<small>S</small>") || !strings.Contains(body, `<html lang="th">`) {
		t.Fatalf("visitor: %d %v\n%s", code, hdr, body)
	}
	// the site's language (site.info)
	admin.do("PUT", "/api/v1/settings", map[string]any{"language": "en"})
	if _, _, body := get("/about"); !strings.Contains(body, `<html lang="en">`) {
		t.Fatalf("language: %s", body)
	}
	admin.do("PUT", "/api/v1/settings", map[string]any{"language": "th"})
	// the admin-wide notice with the bypass link (administrators)
	_, nl := admin.doAny("GET", "/api/v1/code/admin-notices", nil)
	if l := nl.([]any); len(l) != 1 || l[0].(map[string]any)["unit"] != "maintenance" || l[0].(map[string]any)["level"] != "warning" ||
		l[0].(map[string]any)["link"].(map[string]any)["href"] != "/?bypass=s3cret" || !strings.Contains(l[0].(map[string]any)["text"].(string), "Maintenance mode is on") {
		t.Fatalf("notice: %v", nl)
	}
	if _, nl := user("Ed2", "editor").doAny("GET", "/api/v1/code/admin-notices", nil); len(nl.([]any)) != 0 {
		t.Fatalf("editor notice: %v", nl)
	}
	if r := c.send("HEAD", "/about", nil, nil); r.Code != 503 || r.Body.Len() != 0 {
		t.Fatalf("HEAD: %d %d", r.Code, r.Body.Len())
	}
	// never blocked: the API, uploads, plugin assets, the admin's ext-ui pages
	for _, p := range []string{"/api/v1/auth/me", "/uploads/a.png", "/plugin-assets/x/a.js"} {
		if code, _, _ := get(p); code == 503 {
			t.Errorf("%s should not be blocked", p)
		}
	}
	if r := admin.send("GET", "/about", nil, nil); r.Code != 200 { // a CMS user's request (bearer token, e.g. a preview)
		t.Fatalf("admin user blocked: %d", r.Code)
	}
	// 2.1.0: the site's own files, robots.txt and sitemap.xml stay up; openPaths keeps more working
	for _, p := range []string{"/site-assets/qr.js", "/robots.txt", "/sitemap.xml"} {
		if code, _, _ := get(p); code == 503 {
			t.Errorf("%s should not be blocked", p)
		}
	}
	offAPkgSettings(t, admin, "maintenance", map[string]any{"openPaths": "/s/,/status"})
	for p, open := range map[string]bool{"/s/abc": true, "/s": true, "/status": true, "/status/x": true, "/sx": false, "/statuses": false} {
		if code, _, _ := get(p); (code == 503) == open {
			t.Errorf("openPaths %s: %d", p, code)
		}
	}
	offAPkgSettings(t, admin, "maintenance", map[string]any{"openPaths": ""})
	// CMS 2.3.0: an administrator browsing the site in the same browser (session cookie, no header) sees it
	lr := c.send("POST", "/api/v1/auth/login", strings.NewReader(`{"email":"owner@x.io","password":"secret123"}`),
		map[string]string{"X-Anasaki-Session": "cookie", "Content-Type": "application/json"})
	var session string
	for _, ck := range lr.Result().Cookies() {
		if ck.Name == "anasaki_session" {
			session = ck.Value
		}
	}
	if session == "" {
		t.Fatal("no session cookie")
	}
	if r := c.send("GET", "/about", nil, map[string]string{"Cookie": "anasaki_session=" + session}); r.Code != 200 {
		t.Fatalf("admin browsing with the session cookie: %d", r.Code)
	}
	if r := c.send("GET", "/about", nil, map[string]string{"Cookie": "anasaki_session=forged"}); r.Code != 503 {
		t.Fatalf("forged session cookie: %d", r.Code)
	}
	if html, _ := offAAdminPage(t, e, admin, "maintenance:maintenance", ""); !strings.Contains(html, `data-mt="status" data-on="true"`) {
		t.Fatalf("admin page while on:\n%s", html)
	}
	if code, _, _ := get("/about?bypass=wrong"); code != 503 {
		t.Errorf("wrong key: %d", code)
	}
	r := c.send("GET", "/about?bypass=s3cret&x=1", nil, nil)
	if r.Code != http.StatusFound || r.Header().Get("Location") != "/about?x=1" || r.Header().Get("Cache-Control") != "no-store" {
		t.Fatalf("bypass: %d %v", r.Code, r.Header())
	}
	cookies := r.Result().Cookies()
	if len(cookies) != 1 || cookies[0].Name != "pl_maintenance_bypass" || !cookies[0].HttpOnly || cookies[0].MaxAge != 7*24*3600 ||
		strings.Contains(cookies[0].Value, "s3cret") || len(cookies[0].Value) != 32 {
		t.Fatalf("cookie: %+v", cookies)
	}
	if code, hdr, body := get("/about", cookies[0]); code != 200 || !strings.Contains(body, "real site") || hdr.Get("Cache-Control") != "no-store" {
		t.Errorf("with cookie: %d %v", code, hdr)
	}
	if code, _, _ := get("/about", &http.Cookie{Name: "pl_maintenance_bypass", Value: "forged"}); code != 503 {
		t.Errorf("forged cookie: %d", code)
	}
	offAPkgSettings(t, admin, "maintenance", map[string]any{"bypassKey": "rotated"}) // changing the key ends old cookies
	if code, _, _ := get("/about", cookies[0]); code != 503 {
		t.Errorf("old cookie after key change: %d", code)
	}

	// an empty key while on: a random 24-hex key is generated, kept, and shown on the admin page
	offAPkgSettings(t, admin, "maintenance", map[string]any{"bypassKey": "  "})
	st := offACall(t, admin, "maintenance", "status").(map[string]any)
	key, _ := st["bypassKey"].(string)
	if st["enabled"] != true || !regexp.MustCompile(`^[0-9a-f]{24}$`).MatchString(key) || st["bypassPath"] != "/?bypass="+key {
		t.Fatalf("generated key: %v", st)
	}
	if again := offACall(t, admin, "maintenance", "status").(map[string]any); again["bypassKey"] != key {
		t.Fatalf("the generated key must be kept: %v → %v", key, again["bypassKey"])
	}
	html, call := offAAdminPage(t, e, admin, "maintenance:maintenance", "")
	if !strings.Contains(html, `data-mt="link" readonly value="/?bypass=`+key+`"`) || !strings.Contains(html, `data-mt="newkey"`) ||
		!strings.Contains(html, "Real-site link (bypass)") || !strings.Contains(html, `data-mt="title" maxlength="200" value="Back &lt;soon&gt;"`) || !strings.Contains(html, "srcdoc=") {
		t.Fatalf("admin page with generated key:\n%s", html)
	}
	if r := c.send("GET", "/?bypass="+key, nil, nil); r.Code != http.StatusFound || r.Header().Get("Location") != "/" {
		t.Fatalf("generated key bypass: %d %v", r.Code, r.Header())
	}
	if code, out := call("maintenance:newKey", map[string]any{}); code != 200 || offAErr(out) != "" {
		t.Fatalf("new key: %d %v", code, out)
	}
	if st := offACall(t, admin, "maintenance", "status").(map[string]any); st["bypassKey"] == key || len(st["bypassKey"].(string)) != 24 {
		t.Fatalf("new key not applied: %v", st)
	}
	if r := c.send("GET", "/?bypass="+key, nil, nil); r.Code != 503 {
		t.Fatalf("old generated key: %d", r.Code)
	}
	// a key chosen in the settings is kept (no "new key" button; the action refuses)
	offAPkgSettings(t, admin, "maintenance", map[string]any{"bypassKey": "mine"})
	if st := offACall(t, admin, "maintenance", "status").(map[string]any); st["bypassKey"] != "mine" {
		t.Fatalf("own key: %v", st)
	}
	if html, call := offAAdminPage(t, e, admin, "maintenance:maintenance", ""); strings.Contains(html, `data-mt="newkey"`) {
		t.Fatalf("new key button with an own key:\n%s", html)
	} else if _, out := call("maintenance:newKey", map[string]any{}); offAErr(out) == "" {
		t.Fatalf("new key with an own key: %v", out)
	}

	// the settings form of the admin page (site.saveSettings)
	_, call = offAAdminPage(t, e, admin, "maintenance:maintenance", "")
	if code, out := call("maintenance:saveSettings", map[string]any{"enabled": true, "title": "Soon", "message": "", "bypassKey": "mine"}); code != 200 || offAErr(out) != "" {
		t.Fatalf("save settings: %d %v", code, out)
	}
	if _, _, body := get("/about"); !strings.Contains(body, "<h1>Soon</h1>") || !strings.Contains(body, "กรุณากลับมาใหม่") {
		t.Fatalf("after the settings form: %s", body)
	}
	if code, out := call("maintenance:saveSettings", map[string]any{"enabled": true, "title": strings.Repeat("x", 201), "bypassKey": "mine"}); code != 200 || offAErr(out) == "" {
		t.Fatalf("too long title saved: %d %v", code, out)
	}
	if code, _ := user("Ed3", "editor").do("POST", "/api/v1/code/admin-pages/maintenance:maintenance/ticket", map[string]any{}); code != 404 {
		t.Fatalf("editor ticket: %d", code)
	}

	// off again: the real site
	offAPkgSettings(t, admin, "maintenance", map[string]any{"enabled": false})
	if code, _, _ := get("/about"); code != 200 {
		t.Errorf("disabled: %d", code)
	}
	admin.do("PUT", "/api/v1/auth/me", map[string]any{"locale": "th"})
	if html, _ := offAAdminPage(t, e, admin, "maintenance:maintenance", ""); !strings.Contains(html, "ปิดอยู่ — เว็บแสดงตามปกติ") || !strings.Contains(html, `data-on="false"`) {
		t.Fatalf("thai admin page:\n%s", html)
	}
	if code, _ := user("Ed", "editor").do("POST", "/api/v1/code/admin-pages/maintenance:maintenance/ticket", map[string]any{}); code != 404 {
		t.Fatalf("editor ticket: %d", code)
	}
	if got := offACall(t, admin, "maintenance", "legacyImport", map[string]any{"kind": "rows", "table": "x", "rows": []any{}, "last": true}).(map[string]any); got["imported"] != float64(0) {
		t.Fatalf("legacyImport: %v", got)
	}
}
